<?php
namespace App\Jobs; use App\Models\LmsWebhookOutbox; use Illuminate\Bus\Queueable; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Foundation\Bus\Dispatchable; use Illuminate\Queue\InteractsWithQueue; use Illuminate\Queue\SerializesModels; use Illuminate\Support\Facades\Http;
class DeliverLmsWebhook implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public int $tries=5; public function __construct(public string $eventId) { $this->onQueue('lms-webhooks'); } public function backoff(): array { return [30,120,600,1800]; } public function handle(): void { $event=LmsWebhookOutbox::find($this->eventId); if(!$event || $event->delivered_at || blank(config('services.lms_webhook.url')) || blank(config('services.lms_webhook.secret'))) return; $body=json_encode(['event_id'=>$event->id,'type'=>$event->event_type,'data'=>$event->payload], JSON_UNESCAPED_UNICODE); $response=Http::timeout(5)->withHeader('X-SIMANSA-Signature',hash_hmac('sha256',$body,config('services.lms_webhook.secret')))->withBody($body,'application/json')->post(config('services.lms_webhook.url')); if(!$response->successful()) { $event->update(['attempts'=>$event->attempts+1,'last_error'=>'HTTP '.$response->status()]); $response->throw(); } $event->update(['attempts'=>$event->attempts+1,'delivered_at'=>now(),'last_error'=>null]); } }
